@Override public void deletePassword(final String serviceName,final String accountName){
  final String formatted;
  try {
    formatted = String.format("%s@%s", accountName, serviceName);
  } catch (java.util.IllegalFormatException e) {
    throw new RuntimeException("Failed to format service and account names", e);
  }
  final List<String> list=keyring.getItems(this.createAttributes(formatted));
  if (list != null) {
    keyring.deleteItems(list);
  }
}
